function firstMonday(year){const date=new Date(Date.UTC(year,0,4));while(date.getUTCDay()!==1)date.setUTCDate(date.getUTCDate()-1);return date.getTime();}
export function parseDate(text){
 if(typeof text!=='string')throw new TypeError('date');
 const plain=calendar(text);if(plain!==null)return plain;
 const m=/^(\d{4})-W(\d{2})-([1-7])$/.exec(text);if(!m)throw new TypeError('week date');
 const y=Number(m[1]),w=Number(m[2]),d=Number(m[3]);if(y<2000||y>2099)throw new TypeError('year');
 const start=firstMonday(y),weeks=(firstMonday(y+1)-start)/604800000;
 if(w<1||w>weeks)throw new TypeError('week');
